package com.june.activitymonitor.privileged

import android.content.Context
import java.util.UUID

/**
 * Holds the shared secret and connection details for the privileged helper.
 *
 * The token is generated by the app and embedded in the one time adb command shown to the user, so
 * the helper can reject connections from any other app on the device (the loopback port itself is
 * reachable by every app, so a secret is required).
 */
object HelperConfig {

    const val PORT = 41579

    private const val PREFS = "monitor_settings"
    private const val KEY_TOKEN = "helper_token"

    @Volatile
    private var appContext: Context? = null

    fun init(context: Context) {
        appContext = context.applicationContext
    }

    fun token(): String {
        val context = appContext ?: return ""
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        prefs.getString(KEY_TOKEN, null)?.let { if (it.isNotEmpty()) return it }
        val token = UUID.randomUUID().toString().replace("-", "")
        prefs.edit().putString(KEY_TOKEN, token).apply()
        return token
    }
}
